        /* Blue & White Theme */
        body { background-color: #FFFFFF; }
        h1, h2, h3, h4 { color: #013D73; }
        .text-secondary { color: #013D73 !important; }
        /* ONE background for every section: pure white */
        #home, #services, .process-section, #reviews, #contact, #about, #portfolio,
