        .brand-logo-badge { display: flex; align-items: center; justify-content: center; flex-shrink: 0; }

        @media (max-width: 1023px) {
            .hdr-bar-wrap {
                height: 64px;
                border-bottom: 1px solid rgba(16, 81, 223, 0.12);
                box-shadow: none;
            }
            .brand-logo-badge {
