        }

        /* ===================== FLOATING HEADER BAR (rounded, with corner gaps) ===================== */
        .hdr-bar-wrap {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 56px;
            z-index: 9999;
            background: #FFFFFF;
