        .hdr-burger:hover .hdr-bar:nth-child(3) { width: 22px; }
        .hdr-burger:hover .hdr-bar { background: #1051DF; }
        html.dark .hdr-bar { background: #E8F0FF; }
        html.dark .hdr-burger:hover .hdr-bar { background: #6E9BFF; }

        /* ===================== HOW IT WORKS : accent top cards ===================== */
        .pr-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 16px;
            margin-top: 34px;
        }
        @media (min-width: 768px) { .pr-grid { grid-template-columns: 1fr 1fr; gap: 18px; } }
        @media (min-width: 1024px) { .pr-grid { grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 40px; } }

        .pr-card {
            background: #FFFFFF;
            border: 1px solid rgba(16, 81, 223, 0.08);
            border-radius: 18px;
            overflow: hidden;
            box-shadow: 0 10px 28px rgba(1, 61, 115, 0.05);
            transition: transform .3s ease, box-shadow .3s ease;
        }
        .pr-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 18px 40px rgba(1, 61, 115, 0.11);
        }
