            display: inline-block;
            font-size: 10.5px;
            font-weight: 800;
            letter-spacing: 0.14em;
            text-transform: uppercase;
            color: #1051DF;
            background: #EFF4FF;
            border-radius: 999px;
            padding: 4px 11px;
            margin-bottom: 13px;
        }
        .pr-title {
            font-size: 15.5px;
            font-weight: 800;
            letter-spacing: -0.01em;
            color: #013D73;
        }
        .pr-text {
            font-size: 13px;
            line-height: 1.7;
            color: #8B9AAE;
            margin-top: 7px;
        }

        html.dark .pr-card { background: #111C31; border-color: rgba(90, 140, 255, 0.16); box-shadow: 0 10px 28px rgba(0, 0, 0, 0.40); }
        html.dark .pr-step { background: rgba(90, 140, 255, 0.14); color: #8FB4FF; }
        html.dark .pr-title { color: #E8F0FF; }
        html.dark .pr-text { color: #A9BAD4; }

        /* ===================== CONTACT ===================== */
        .ct-kicker {
            display: inline-block;
            font-size: 12px;
            font-weight: 800;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: #1051DF;
        }
        .ct-title { font-size: clamp(1.85rem, 4vw, 2.7rem); line-height: 1.16; letter-spacing: -0.02em; color: #013D73; }
        .ct-sub { font-size: 15px; line-height: 1.7; max-width: 34rem; }

        .ct-card {
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
            gap: 0;
            padding: 34px 26px;
            background: #FFFFFF;
            border: 1px solid rgba(16, 81, 223, 0.07);
