        /* ---------- Mobile layout: text → video card → buttons (as reference) ---------- */
        @media (max-width: 1023px) {
            .hero-grid { gap: 1.6rem; }
            .hero-title .hero-line-1 { font-size: clamp(1.32rem, 5.1vw, 1.72rem); }
            .hero-title .hero-line-2 { font-size: clamp(1.85rem, 8.2vw, 2.6rem); margin-top: 5px; white-space: normal; text-wrap: balance; }
            .hero-badge { margin-bottom: 1.5rem; }
