<script id="mm-img-guard">
/* If a remote image cannot load (offline / blocked), hide the broken icon so the dark
   placeholder behind it shows instead of a torn-image marker. */
(function () {
    function hide(el) {
        if (String(el.getAttribute('src') || '').indexOf('data:') === 0) return;
        el.style.visibility = 'hidden';
        el.setAttribute('aria-hidden', 'true');
    }
    function sweep() {
        document.querySelectorAll('img').forEach(function (img) {
            if (img.src.indexOf('data:') !== 0 && img.complete && img.naturalWidth === 0) hide(img);
        });
    }
    document.addEventListener('error', function (e) {
        if (e.target && e.target.tagName === 'IMG') hide(e.target);
    }, true);
    document.addEventListener('DOMContentLoaded', sweep);
    window.addEventListener('load', sweep);
    var n = 0, t = setInterval(function () { sweep(); if (++n > 12) clearInterval(t); }, 500);
})();
</script>
<style id="home-ui-fixes">
/* ============================================================================
   HOME PAGE — UI FIXES
   Loaded last so these rules win over the page's stacked stylesheets.
   ============================================================================ */

/* --- 3 · team member cards: one single box (no frame around the photo) --- */
#team .tm-card {
    padding: 0 !important;
    overflow: hidden;
}
#team .tm-card .tm-photo {
    width: 100%;
    border: 0 !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
}
#team .tm-card .tm-body { padding: 14px 12px 18px; }
#team .tm-card:hover { transform: translateY(-4px); }

/* --- 2 · team perks: crisp stroke icons in a proper tile (was a 22px square) --- */
.tm-perk-ic {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    flex: 0 0 38px;
    border-radius: 11px;
}
.tm-perk-ic .tm-perk-svg { width: 1em; height: 1em; display: block; }
@media (max-width: 640px) {
    .tm-perk-ic { width: 34px; height: 34px; flex-basis: 34px; border-radius: 10px; }
}

/* --- 4 · about: rating star matches the review-card star colour --- */
.abt-float-ic,
.abt-float-ic i { color: #FACC15 !important; }

/* --- 5 · contact: no stray box/border behind the icons --- */
#contact .ct-icon {
    height: auto;
    font-size: 26px;
    margin-bottom: 14px;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
}

/* --- 6 · footer wordmark: M mark + word read as one clean lockup --- */
/* the page pins this image to 22px with a high-specificity rule, so match its weight */
footer a img.object-contain.flex-shrink-0[alt="Mexa Motion M"] {
    height: 22px !important;
    width: auto !important;
    margin-right: 0 !important;
}
footer .footer-brand-word {
    margin-left: -9px !important;
    top: 0 !important;
    line-height: 1.05;
}
@media (max-width: 1023px) {
    footer a img.object-contain.flex-shrink-0[alt="Mexa Motion M"] {
        height: 20px !important;
        position: relative;
        top: -1px;
    }
    footer .footer-brand-word { margin-left: -10px !important; }
}
</style>

<script id="mx-ux-fix">
/* TASK 09 · small responsiveness fixes — no feature, layout or copy change */
(function () {
  "use strict";

  /* 1 · placeholder links must not scroll the page to the top */
  document.addEventListener("click", function (e) {
    var a = e.target && e.target.closest ? e.target.closest('a[href="#"]') : null;
    if (a) e.preventDefault();
  }, false);

  /* 2 · real addresses for the footer icons that already exist on the page */
  var SOCIAL = {
    "fa-telegram": "https://t.me/mexamotion",
    "fa-telegram-plane": "https://t.me/mexamotion",
    "fa-whatsapp": "https://wa.me/8801700000000"
  };
  function wireSocial() {
    var icons = document.querySelectorAll(".fa-telegram, .fa-telegram-plane, .fa-whatsapp");
    for (var i = 0; i < icons.length; i++) {
      var ic = icons[i];
      var key = ic.classList.contains("fa-whatsapp") ? "fa-whatsapp" : "fa-telegram";
      var link = ic.closest ? ic.closest("a") : null;
      if (link && (!link.getAttribute("href") || link.getAttribute("href") === "#")) {
        link.setAttribute("href", SOCIAL[key]);
        link.setAttribute("target", "_blank");
        link.setAttribute("rel", "noopener");
      }
    }
  }

  /* 3 · never leave a broken-image icon in a card */
  function guardImages() {
    var imgs = document.images;
    for (var i = 0; i < imgs.length; i++) {
      var img = imgs[i];
      if (img.complete && img.naturalWidth === 0 && img.getAttribute("src")) {
        img.setAttribute("data-img-broken", "1");
      }
      img.addEventListener("error", function () {
        this.setAttribute("data-img-broken", "1");
      }, { once: true });
    }
  }

  function boot() { wireSocial(); guardImages(); }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
  window.addEventListener("load", boot);
})();
</script>
<script id="mm-hero-character-js">

/* Hero character: lightweight hover/touch lift + best-effort image protection. */
(function () {
    var el = document.getElementById('hero-character');
    if (!el) return;
    function block(e) { e.preventDefault(); }
    el.addEventListener('contextmenu', block);
    el.addEventListener('dragstart', block);
    el.addEventListener('selectstart', block);
    function release() { el.classList.remove('is-touch'); }
    el.addEventListener('pointerdown', function (e) {
        if (e.pointerType === 'touch' || e.pointerType === 'pen') el.classList.add('is-touch');
    }, { passive: true });
    el.addEventListener('pointerup', release, { passive: true });
    el.addEventListener('pointercancel', release, { passive: true });
    el.addEventListener('pointerleave', release, { passive: true });
    window.addEventListener('blur', release, { passive: true });
})();

</script>
@include('pages.partials.video-assets')
